'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import { ndarray as strided } from '@stdlib/blas-ext-base-dcusome';


// MAIN //

/**
* Cumulatively tests whether at least `k` elements in a one-dimensional double-precision floating-point ndarray are truthy.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*     -   a zero-dimensional ndarray specifying the minimum number of truthy elements.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import BooleanVector from '@stdlib/ndarray-vector-bool';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = new Float64Vector( [ 0.0, 0.0, 1.0, 1.0, 1.0 ] );
* var out = new BooleanVector( 5 );
*
* var k = scalar2ndarray( 2, {
*     'dtype': 'generic'
* });
*
* var z = dcusome( [ x, out, k ] );
* // returns <ndarray>[ false, false, false, true, true ]
*
* var bool = ( z === out );
* // returns true
*/
function dcusome( arrays ) {
	var out = arrays[ 1 ];
	var x = arrays[ 0 ];
	var k = ndarraylike2scalar( arrays[ 2 ] );
	strided( numelDimension( x, 0 ), k, getData( x ), getStride( x, 0 ), getOffset( x ), getData( out ), getStride( out, 0 ), getOffset( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

export default dcusome;
