'use strict';

/**
* Subtract a scalar constant from each element in a one-dimensional single-precision complex floating-point ndarray.
*
* @module @stdlib/blas-ext-base-ndarray-cxsa
*
* @example
* import Complex64Vector from '@stdlib/ndarray-vector-complex64';
* import Complex64 from '@stdlib/complex-float32-ctor';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
* import cxsa from '@stdlib/blas-ext-base-ndarray-cxsa';
*
* var x = new Complex64Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
*
* var alpha = scalar2ndarray( new Complex64( 5.0, 0.0 ), {
*     'dtype': 'complex64'
* });
*
* var out = cxsa( [ x, alpha ] );
* // returns <ndarray>[ <Complex64>[ -7.0, 1.0 ], <Complex64>[ -2.0, -5.0 ] ]
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var cxsa;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	cxsa = main;
} else {
	cxsa = tmp;
}


// EXPORTS //

export default cxsa;
