'use strict';

/**
* Test whether every element in a one-dimensional double-precision floating-point ndarray is falsy.
*
* @module @stdlib/blas-ext-base-ndarray-dnone
*
* @example
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import dnone from '@stdlib/blas-ext-base-ndarray-dnone';
*
* var x = new Float64Vector( [ 0.0, 0.0, 1.0, 1.0 ] );
*
* var v = dnone( [ x ] );
* // returns false
*/

// MODULES //

var join = require( 'path' ).join;
import tryRequire from '@stdlib/utils-try-require';
import isError from '@stdlib/assert-is-error';
import main from './main.js';


// MAIN //

var dnone;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dnone = main;
} else {
	dnone = tmp;
}


// EXPORTS //

export default dnone;
